    const bp = result.violations.filter((v) => v.tags.includes('best-practice'));
    return {
      wcag: wcag.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
      bp: bp.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) }))
    };
  };

  const summary = { default: format(defaultResults), dialogOpen: format(dialogResults) };
  console.log(JSON.stringify(summary, null, 2));
  if (summary.default.wcag.length || summary.dialogOpen.wcag.length) process.exit(1);
})().catch((error) => {
  console.error(error.message);
  process.exit(2);
});
