     }

     .dialog-actions {
       display: flex;
       flex-wrap: wrap-reverse;
       gap: 0.75rem;
       justify-content: flex-end;
     }

     .deleted-state {
       display: grid;
       min-height: 360px;
       place-items: center;
       padding: 48px 24px;
       text-align: center;
     }

     .deleted-state svg {
       color: var(--primary);
       margin-bottom: 1rem;
     }

