   <div id="root"></div>

   <script>
     const imageData = {
       title: 'Golden hour ridge',
       location: 'Dolomites, Italy',
       added: 'May 4, 2026',
       size: '8.4 MB',
       dimensions: '3840 x 2400',
       alt: 'Golden mountain ridge at sunset above a blue valley',
       src: 'data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%220%200%201600%201000%22%3E%3Cdefs%3E%3ClinearGradient%20id=%22sky%22%20x1=%220%22%20x2=%220%22%20y1=%220%22%20y2=%221%22%3E%3Cstop%20stop-color=%22%2398c9ff%22/%3E%3Cstop%20offset=%22.55%22%20stop-color=%22%23f8c987%22/%3E%3Cstop%20offset=%221%22%20stop-color=%22%2335486f%22/%3E%3C/linearGradient%3E%3ClinearGradient%20id=%22mountain%22%20x1=%220%22%20x2=%221%22%3E%3Cstop%20stop-color=%22%23223648%22/%3E%3Cstop%20offset=%221%22%20stop-color=%22%236f7d8e%22/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect%20width=%221600%22%20height=%221000%22%20fill=%22url(%23sky)%22/%3E%3Ccircle%20cx=%221195%22%20cy=%22260%22%20r=%22120%22%20fill=%22%23fff2b6%22/%3E%3Cpath%20d=%22M0%20780%20315%20420%20548%20670%20775%20300%201012%20690%201215%20470%201600%20790v210H0z%22%20fill=%22url(%23mountain)%22/%3E%3Cpath%20d=%22M0%20850c210-95%20352-94%20534%200s364%2090%20544%200%20325-96%20522-8v158H0z%22%20fill=%22%231d2b45%22%20opacity=%22.72%22/%3E%3Cpath%20d=%22M775%20300%20670%20474l110-47%2086%2063zM315%20420l-88%20101%2093-34%2072%2072zM1215%20470l-70%2075%2072-26%2062%2061z%22%20fill=%22%23f7fbff%22%20opacity=%22.86%22/%3E%3C/svg%3E'
     };

     function IconTrash() {
       return `
         <svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none">
           <path d="M4 7h16M10 11v6M14 11v6M6 7l1 14h10l1-14M9 7V4h6v3" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
         </svg>
       `;
     }

     function IconCheck() {
       return `
         <svg aria-hidden="true" width="56" height="56" viewBox="0 0 24 24" fill="none">
           <path d="M20 6 9 17l-5-5" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>
         </svg>
       `;
     }

     function Header() {
       return `
         <header class="topbar">
           <div class="brand">
             <span class="brand-mark" aria-hidden="true">F</span>
             <span>Framebox</span>
           </div>
           <div class="header-actions">
             <a class="button button-ghost" href="#details">View details</a>
             <button class="button button-primary" type="button">Download</button>
           </div>
         </header>
       `;
     }

     function Hero() {
       return `
         <section class="hero">
           <div>
             <p class="eyebrow">Image preview</p>
             <h1 id="page-title">${imageData.title}</h1>
             <p class="lede">Review this image before making changes to your library. Deleting it will remove the saved file and its metadata from your collection.</p>
           </div>
           <p class="status" id="status" aria-live="polite"></p>
         </section>
       `;
     }

     function ImagePreview() {
       return `
         <section class="image-card" aria-labelledby="image-title">
           <div class="image-frame">
             <img src="${imageData.src}" alt="${imageData.alt}">
           </div>
           <div class="image-meta">
             <div>
               <h2 class="image-title" id="image-title">${imageData.title}</h2>
               <p class="meta-line">${imageData.location} · Added ${imageData.added}</p>
             </div>
             <button class="button button-danger trigger" type="button" aria-haspopup="dialog">
               ${IconTrash()}
               Delete image
             </button>
           </div>
         </section>
       `;
     }

     function ImageDetails() {
       return `
         <aside class="details-card" id="details" aria-labelledby="details-title">
           <h2 id="details-title">File details</h2>
           <dl class="detail-list">
             <div class="detail-row">
               <dt>Location</dt>
               <dd>${imageData.location}</dd>
             </div>
             <div class="detail-row">
               <dt>Dimensions</dt>
               <dd>${imageData.dimensions}</dd>
             </div>
             <div class="detail-row">
               <dt>File size</dt>
               <dd>${imageData.size}</dd>
             </div>
             <div class="detail-row">
               <dt>Library status</dt>
               <dd>Saved</dd>
             </div>
           </dl>
         </aside>
       `;
     }

     function DeleteConfirmationDialog() {
       return `
         <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
           <div class="dialog-content">
             <div class="dialog-icon" aria-hidden="true">${IconTrash()}</div>
             <h2 id="dialog-title">Delete this image?</h2>
             <p id="dialog-description">This will permanently remove "${imageData.title}" from your library. This action cannot be undone.</p>
             <div class="dialog-actions">
               <button class="button" type="button" data-close>Cancel</button>
               <button class="button button-danger" type="button" data-confirm>Delete image</button>
             </div>
           </div>
         </dialog>
       `;
     }

     function DeletedState() {
       return `
         <section class="image-card deleted-state" aria-labelledby="deleted-title">
           ${IconCheck()}
           <div>
             <h2 id="deleted-title" tabindex="-1">Image deleted</h2>
             <p class="meta-line">The image has been removed from your library.</p>
           </div>
         </section>
       `;
     }

     function App() {
       return `
         <div class="app-shell">
           ${Header()}
           <main id="main" tabindex="-1">
             ${Hero()}
             <div class="preview-layout" id="preview-layout">
               ${ImagePreview()}
               ${ImageDetails()}
             </div>
           </main>
         </div>
         ${DeleteConfirmationDialog()}
       `;
     }

     function setupDeleteDialog() {
       const dialog = document.querySelector('#delete-dialog');
       const trigger = document.querySelector('.trigger');
       const cancelButton = dialog.querySelector('[data-close]');
       const confirmButton = dialog.querySelector('[data-confirm]');
       const status = document.querySelector('#status');
       const previewLayout = document.querySelector('#preview-layout');

       trigger.addEventListener('click', () => {
         dialog.showModal();
         cancelButton.focus();
       });

       cancelButton.addEventListener('click', () => {
         dialog.close('cancel');
       });

       confirmButton.addEventListener('click', () => {
         dialog.close('delete');
         previewLayout.innerHTML = DeletedState();
         status.textContent = 'Image deleted from your library.';
         document.querySelector('#deleted-title').focus?.();
       });

       dialog.addEventListener('click', (event) => {
         if (event.target === dialog) {
           dialog.close('cancel');
         }
       });
     }

     document.querySelector('#root').innerHTML = App();
     setupDeleteDialog();
   </script>
